class Solution {
    public int countPairs(List<Integer> nums, int target) {
        List<Integer> sorted = new ArrayList<>(nums);
        Collections.sort(sorted);
        int left = 0;
        int right = sorted.size() - 1;
        int answer = 0;
        while (left < right) {
            if ((long) sorted.get(left) + sorted.get(right) < target) {
                answer += right - left;
                left++;
            } else {
                right--;
            }
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public int countPairs(List<Integer> nums, int target) {
        List<Integer> sorted = new ArrayList<>(nums);
        Collections.sort(sorted);
        int answer = 0;
        for (int left = 0; left < sorted.size(); left++) {
            int boundary = lowerBound(sorted, left + 1, sorted.size(), (long) target - sorted.get(left));
            answer += boundary - left - 1;
        }
        return answer;
    }

    private int lowerBound(List<Integer> nums, int left, int right, long value) {
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums.get(mid) < value) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

import java.util.*;

class Solution {
    public int countPairs(List<Integer> nums, int target) {
        List<Integer> values = new ArrayList<>(nums);
        Collections.sort(values);
        List<Integer> unique = new ArrayList<>();
        for (int value : values) {
            if (unique.isEmpty() || unique.get(unique.size() - 1) != value) {
                unique.add(value);
            }
        }

        int[] bit = new int[unique.size() + 1];
        int answer = 0;
        for (int current : nums) {
            int countLessThan = lowerBound(unique, (long) target - current);
            answer += sum(bit, countLessThan);
            int index = lowerBound(unique, current) + 1;
            add(bit, index, 1);
        }
        return answer;
    }

    private int lowerBound(List<Integer> values, long target) {
        int left = 0;
        int right = values.size();
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (values.get(mid) < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    private void add(int[] bit, int index, int delta) {
        while (index < bit.length) {
            bit[index] += delta;
            index += index & -index;
        }
    }

    private int sum(int[] bit, int index) {
        int total = 0;
        while (index > 0) {
            total += bit[index];
            index -= index & -index;
        }
        return total;
    }
}

class Solution {
    public int countPairs(List<Integer> nums, int target) {
        int[] values = new int[nums.size()];
        for (int i = 0; i < nums.size(); i++) {
            values[i] = nums.get(i);
        }
        int[] temp = new int[values.length];
        return (int) sortAndCount(values, temp, 0, values.length, target);
    }

    private long sortAndCount(int[] values, int[] temp, int left, int right, int target) {
        if (right - left <= 1) {
            return 0;
        }
        int mid = left + (right - left) / 2;
        long answer = sortAndCount(values, temp, left, mid, target)
                + sortAndCount(values, temp, mid, right, target);

        int j = mid;
        for (int i = mid - 1; i >= left; i--) {
            while (j < right && (long) values[i] + values[j] < target) {
                j++;
            }
            answer += j - mid;
        }

        merge(values, temp, left, mid, right);
        return answer;
    }

    private void merge(int[] values, int[] temp, int left, int mid, int right) {
        int i = left;
        int j = mid;
        int k = left;
        while (i < mid && j < right) {
            if (values[i] <= values[j]) {
                temp[k++] = values[i++];
            } else {
                temp[k++] = values[j++];
            }
        }
        while (i < mid) {
            temp[k++] = values[i++];
        }
        while (j < right) {
            temp[k++] = values[j++];
        }
        System.arraycopy(temp, left, values, left, right - left);
    }
}

class Solution {
    public int countPairs(List<Integer> nums, int target) {
        int answer = 0;
        for (int i = 0; i < nums.size(); i++) {
            for (int j = i + 1; j < nums.size(); j++) {
                if ((long) nums.get(i) + nums.get(j) < target) {
                    answer++;
                }
            }
        }
        return answer;
    }
}
